mapper.select:
SELECT pno, title, content, category, submitter, status,
       total_score AS totalScore, deadline, regdate, updatedate
FROM tbl_proposal
WHERE submitter = #{submitter}
ORDER BY pno DESC
LIMIT #{pageStart}, #{perPageNum}

mapper.update:
UPDATE tbl_proposal
SET status = #{status}, updatedate = NOW()
WHERE pno = #{pno}

UPDATE tbl_proposal
SET total_score = #{totalScore}, status = 'COMPLETED', updatedate = NOW()
WHERE pno = #{pno}
